def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_moves = [h[1] for h in history]
    my_moves = [h[0] for h in history]

    opp_c = opp_moves.count('C')
    opp_d = n - opp_c
    my_c = my_moves.count('C')
    my_d = n - my_c

    last_my = my_moves[-1]
    last_opp = opp_moves[-1]

    opp_defected_first = False
    for i in range(n):
        if my_moves[i] == 'D' or opp_moves[i] == 'D':
            if opp_moves[i] == 'D' and my_moves[i] == 'C':
                opp_defected_first = True
            break

    if opp_defected_first:
        return 'D'

    if n == 99:
        return 'D'

    if my_d == 0:
        if n < 5:
            return 'C'
        else:
            return 'D'

    if opp_d == 0:
        return 'D'

    if last_opp == 'D':
        recent_my_def = my_moves[-10:].count('D')
        if recent_my_def >= 2:
            return 'C'
        return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
